$('storage').onclick=async()=>{try{const data=await api('/api/storage');const box=document.createElement('div');for(const text of ['已提交的更改自动保存到运行服务的这台电脑：',data.database,'导入 XMind 是创建一个协作副本，不会修改或覆盖原 .xmind 文件。其他电脑上的编辑也保存到这台服务电脑。','需要独立文件备份，请点击「导出 → JSON」。换电脑或备份整个工作空间时，请先停止服务，再复制 data 文件夹。侧栏未提交的文字草稿只保存在当前浏览器。']){const p=document.createElement('p');p.textContent=text;box.append(p);}modal('保存位置与备份',box);}catch(e){toast(e.message);}};

function toast(message,time=5000){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,time);}
async function api(path,options={}){const headers=new Headers(options.headers||{});if(S.name)headers.set('X-GNN-Name',encodeURIComponent(S.name));const r=await fetch(path,{...options,headers});if(!r.ok){let e;try{e=await r.json();}catch{}throw Error(typeof e?.detail==='string'?e.detail:`请求失败 (${r.status})`);}return r.json();}
function modal(title,content){$('modalTitle').textContent=title;$('modalBody').replaceChildren();if(typeof content==='string'){const p=document.createElement('p');p.textContent=content;$('modalBody').append(p);}else $('modalBody').append(content);if(!$('modal').open)$('modal').showModal();}
$('closeModal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close();};
function current(){return S.doc?.nodes[S.selected];}
function online(){return S.socket?.readyState===WebSocket.OPEN;}
function setStatus(connected){$('connection').className=connected?'':'offline';$('connection').replaceChildren();const dot=document.createElement('span');dot.className='tiny-dot';$('connection').append(dot,connected?'实时同步已连接':'已断开，正在重连');$('saveStatus').textContent=connected?'所有更改已保存':'离线 · 编辑暂不可用';updateDisabled();}
function topicsFor(node=current()){if(S.selection.size>1)return [...S.selection];return node?.children.length?[...node.children]:node?[node.id]:[];}
function selectedAnnotation(kind){const topics=new Set(topicsFor());return (S.doc?.annotations||[]).find(item=>item.kind===kind&&item.topics.length===topics.size&&item.topics.every(id=>topics.has(id)));}
function setToolLabel(id,label,title){const button=$(id);button.querySelector('span')?.replaceChildren(label);button.title=title;button.setAttribute('aria-label',title);}
function updateAnnotationActions(){const boundary=selectedAnnotation('boundary'),summary=selectedAnnotation('summary');setToolLabel('boundary',boundary?'取消边界':'边界',boundary?'取消当前分支的边界':'为当前分支添加边界');setToolLabel('summary',summary?'取消概要':'概要',summary?'取消当前分支的概要':'为当前分支添加概要');}
function updateDisabled(){const n=current(),disabled=!online()||!n;for(const id of ['addChild','addSibling','addParent','relationship','boundary','summary','deleteNode','moveUp','moveDown'])$(id).disabled=disabled||(['addSibling','addParent','deleteNode','moveUp','moveDown'].includes(id)&&n?.id===S.doc?.root);$('renameDoc').disabled=disabled||!S.doc?.root;$('saveNode').disabled=disabled||!S.draft?.dirty||S.draft?.busy;$('undo').disabled=disabled||S.undoBusy||S.pending.size>0||!S.undo.length;$('redo').disabled=disabled||S.undoBusy||S.pending.size>0||!S.redo.length;for(const id of ['focusBranch','focusBranchTop'])$(id).disabled=!n||(n.id===S.doc?.root&&!S.focusRoot);updateAnnotationActions();}
function draftKey(doc,node){return `mindcollab:draft:${doc}:${node}`;}
function safeStore(key,value){try{localStorage.setItem(key,value);}catch{}}
// Camera state belongs to this browser, never to the shared document or presence.
function rememberView(){if(!S.doc||S.focusRoot)return;const {width,height}=$('canvas').getBoundingClientRect(),{x,y,k}=S.transform;if(width>0&&height>0)safeStore(`mindcollab:view:${S.doc.id}`,JSON.stringify({x:(width/2-x)/k,y:(height/2-y)/k,k}));}
function restoreView(id){try{const view=JSON.parse(localStorage.getItem(`mindcollab:view:${id}`));if(!view||![view.x,view.y,view.k].every(Number.isFinite)||view.k<.12||view.k>2.5)return false;const {width,height}=$('canvas').getBoundingClientRect();S.transform={x:width/2-view.x*view.k,y:height/2-view.y*view.k,k:view.k};return true;}catch{return false;}}
function preserveDraft(){if(S.draft?.dirty){safeStore(draftKey(S.doc.id,S.draft.node),JSON.stringify({...S.draft,busy:false}));}}
function loadInspector(){const n=current();if(!n)return;let saved=null;try{saved=JSON.parse(localStorage.getItem(draftKey(S.doc.id,n.id)));}catch{}
 S.draft=saved?.dirty?saved:{node:n.id,title:n.title,notes:n.notes,base:{title:n.rev.title,notes:n.rev.notes},dirty:false,busy:false};
 $('nodeTitle').value=S.draft.title;$('nodeNotes').value=S.draft.notes;updateInspector();}
function updateInspector(){const n=current();if(!n)return;$('nodeKind').textContent=n.id===S.doc.root?'中心主题':'分支主题';$('childCount').textContent=n.children.length;$('branchCount').textContent=countBranch(n.id)-1;
 $('colors').replaceChildren();const colorNames={blue:'蓝色',teal:'青绿',amber:'琥珀',rose:'玫红',violet:'紫色',slate:'灰色',coral:'珊瑚',orange:'橙色',yellow:'黄色',green:'绿色',mint:'薄荷',cyan:'青色',sky:'天蓝',indigo:'靛蓝',fuchsia:'洋红',brown:'棕色'};for(const [color,p]of Object.entries(palette)){const b=document.createElement('button');b.className='color-option'+(n.color===color?' active':'');b.style.background=p.swatch;b.title=colorNames[color];b.setAttribute('aria-label',b.title);b.disabled=!online();b.onclick=()=>perform({kind:'edit',node:n.id,field:'color',value:color,expected:n.rev.color});$('colors').append(b);}
 const conflict=S.draft?.dirty&&(S.draft.base.title!==n.rev.title||S.draft.base.notes!==n.rev.notes);
 $('draftHint').className='draft-hint'+(conflict?' conflict':'');$('draftHint').textContent=conflict?'其他人更新了此节点，你的草稿已保留。点击保存时将询问是否基于最新版本提交。':S.draft?.dirty?'草稿保存在此浏览器，尚未同步。':'修改后点击保存，实时同步给其他人。';syncAdvancedControls();updateDisabled();}
function countBranch(id){let count=0,stack=[id];while(stack.length){const node=S.doc.nodes[stack.pop()];if(!node)continue;count++;for(let i=node.children.length-1;i>=0;i--)stack.push(node.children[i]);}return count;}
function toggleCollapse(id){const node=S.doc?.nodes[id];if(!node?.children.length)return;if(S.collapsed.has(id))S.collapsed.delete(id);else S.collapsed.add(id);render();}

function viewRoot(){return S.focusRoot||S.doc?.root;}
function resetFocusView(){S.focusRoot=null;S.focusTrail=[];S.focusAncestors=[];S.focusMembers=null;$('focusBar').hidden=true;$('canvas').classList.remove('branch-focused');}
function reconcileFocus(){
 if(S.focusRoot&&!S.doc.nodes[S.focusRoot]){
  const parent=S.focusAncestors.find(id=>S.doc.nodes[id]);
  S.focusRoot=parent&&parent!==S.doc.root?parent:null;
  S.focusTrail=S.focusTrail.filter(item=>!item.root||S.doc.nodes[item.root]);
  toast(S.focusRoot?'当前分支已被删除，已返回它的上级分支。':'当前分支已被删除，已返回全图。');
 }
 S.focusAncestors=S.focusRoot?ancestorIds(S.doc.nodes,S.focusRoot):[];
 S.focusMembers=S.focusRoot?branchIds(S.doc.nodes,S.focusRoot):null;
}
function updateFocusBar(){
 const focused=!!S.focusRoot;
 $('focusBar').hidden=!focused;$('canvas').classList.toggle('branch-focused',focused);
 $('focusPath').replaceChildren();
 if(!focused)return;
 for(const id of [...S.focusAncestors].reverse().concat(S.focusRoot)){
  const button=document.createElement('button');button.textContent=S.doc.nodes[id].title;button.title=button.textContent;
  button.disabled=id===S.focusRoot;
  button.onclick=()=>id===S.doc.root?leaveFocus(true):focusBranch(id);
  $('focusPath').append(button);
 }
 $('focusCount').textContent=`本分支 ${S.focusMembers.size} 个 / 全图 ${Object.keys(S.doc.nodes).length} 个节点 · 修改自动保存到原导图`;
}
async function focusBranch(id=S.selected){
 if(!S.doc?.nodes[id])return;
 if(S.inline)await finishInline(true);
 if(!S.doc?.nodes[id])return;
 if(id===S.doc.root){leaveFocus(true);return;}
 if(id===S.focusRoot)return;
 rememberView();
 S.focusTrail.push({root:S.focusRoot,transform:{...S.transform}});
 S.focusRoot=id;S.collapsed.delete(id);reconcileFocus();
 preserveDraft();S.selected=id;S.selection=new Set([id]);loadInspector();presence();render();fit();
}
function leaveFocus(all=false,renderNow=true){
 if(!S.focusRoot)return;
 const previous=all?S.focusTrail[0]:S.focusTrail.pop();
 if(all)S.focusTrail=[];
 S.focusRoot=previous?.root&&S.doc.nodes[previous.root]?previous.root:null;
 if(previous)S.transform={...previous.transform};
 reconcileFocus();
 if(renderNow){
  if(!S.doc.nodes[S.selected]||(S.focusMembers&&!S.focusMembers.has(S.selected))){
   preserveDraft();S.selected=viewRoot();S.selection=new Set([S.selected]);loadInspector();presence();
  }
  render();
 }
}
function highlightLineage(){
 if(!S.doc)return;
 const {ancestors,descendants}=selectionLineage(S.doc.nodes,S.selection,S.doc.root);
 for(const node of $('nodes').querySelectorAll('[data-node]')){
  const id=node.dataset.node,selected=S.selection.has(id);
  node.classList.toggle('selected',selected);
  node.classList.toggle('lineage-ancestor',!selected&&ancestors.has(id));
  node.classList.toggle('lineage-descendant',!selected&&descendants.has(id)&&!ancestors.has(id));
 }
 for(const edge of $('edges').children){
  const id=edge.dataset.child,parent=S.doc.nodes[id]?.parent;
  const path=ancestors.has(parent)&&(ancestors.has(id)||S.selection.has(id));
  edge.classList.toggle('lineage-path',path);
  edge.classList.toggle('lineage-branch',!path&&descendants.has(id));
 }
}
$('focusBranch').onclick=()=>focusBranch();
$('focusBranchTop').onclick=()=>focusBranch();
$('focusBack').onclick=()=>leaveFocus();
$('focusAll').onclick=()=>leaveFocus(true);

const themeDefaults={
 original:{background:'#f7f8fc',root:'#4c6fdb'},ocean:{background:'#f2f8fa',root:'#167a8b'},forest:{background:'#f4f8f3',root:'#397353'},
 ink:{background:'#f3f3f2',root:'#292d32'},pastel:{background:'#fff8fb',root:'#b4587b'},sunset:{background:'#fff8f1',root:'#c56842'}
};
function feature(kind,payload={}){S.featureQueue=(S.featureQueue||Promise.resolve()).catch(()=>{}).then(()=>operation({kind,...payload,expected_version:S.doc.version}));return S.featureQueue;}
function syncAdvancedControls(){const n=current();if(!n||!S.doc)return;const style=n.style||{},meta=n.meta||{};
 $('nodeShape').value=style.shape||(n.id===S.doc.root?'roundedRect':'underline');$('fontSize').value=style.fontSize||(n.id===S.doc.root?15:13);$('bold').classList.toggle('active',style.bold===true);$('italic').classList.toggle('active',style.italic===true);
 $('fillColor').value=validHex(style.fill)?style.fill:(n.id===S.doc.root?(themeDefaults[S.doc.theme||'original']?.root||'#4c6fdb'):(palette[n.color]?.fill||'#edf2ff'));
 $('textColor').value=validHex(style.text)?style.text:(n.id===S.doc.root?'#ffffff':palette[n.color]?.text||'#4e70c6');$('borderColor').value=validHex(style.border)?style.border:$('fillColor').value;
 $('priority').value=String(meta.priority||0);$('progress').value=String(meta.progress??-1);$('labels').value=(meta.labels||[]).join(', ');$('nodeLink').value=meta.link||'';$('removeImage').disabled=!meta.image;
 $('theme').value=S.doc.theme||'original';$('lineType').value=S.doc.lineType||'elbow';$('lineWidth').value=String(S.doc.lineWidth||2);$('spacing').value=S.doc.spacing||'normal';$('background').value=validHex(S.doc.background)?S.doc.background:(themeDefaults[S.doc.theme||'original']?.background||'#f7f8fc');
 document.querySelectorAll('#layouts button').forEach(b=>b.classList.toggle('active',b.dataset.value===(S.doc.layout||'balanced')));
}
function validHex(value){return /^#[0-9a-f]{6}$/i.test(value||'');}
for(const button of document.querySelectorAll('.inspector-tabs button'))button.onclick=()=>{document.querySelectorAll('.inspector-tabs button').forEach(b=>b.classList.toggle('active',b===button));for(const panel of document.querySelectorAll('.inspector-panel'))panel.hidden=panel.id!==button.dataset.panel;};
for(const [id,key,convert] of [['nodeShape','shape',String],['fontSize','fontSize',Number],['fillColor','fill',String],['textColor','text',String],['borderColor','border',String]])$(id).onchange=()=>feature('style',{nodes:[S.selected],patch:{[key]:convert($(id).value)}}).catch(e=>toast(e.message));
$('bold').onclick=()=>feature('style',{nodes:[S.selected],patch:{bold:!(current().style?.bold)}}).catch(e=>toast(e.message));$('italic').onclick=()=>feature('style',{nodes:[S.selected],patch:{italic:!(current().style?.italic)}}).catch(e=>toast(e.message));
for(const [id,key,convert] of [['priority','priority',Number],['progress','progress',Number]])$(id).onchange=()=>feature('meta',{nodes:[S.selected],patch:{[key]:convert($(id).value)}}).catch(e=>toast(e.message));
$('labels').onchange=()=>{const labels=$('labels').value.split(/[,，]/).map(v=>v.trim()).filter(Boolean).slice(0,8);feature('meta',{nodes:[S.selected],patch:{labels}}).catch(e=>toast(e.message));};
$('nodeLink').onchange=()=>feature('meta',{nodes:[S.selected],patch:{link:$('nodeLink').value.trim()}}).catch(e=>toast(e.message));$('openLink').onclick=()=>{const url=current()?.meta?.link;if(url)window.open(url,'_blank','noopener');else toast('请先填写并保存链接。');};
$('chooseImage').onclick=()=>$('imageInput').click();$('imageInput').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>300000)return toast('图片不能超过 300 KB。');const reader=new FileReader();reader.onload=()=>feature('meta',{nodes:[S.selected],patch:{image:reader.result}}).catch(err=>toast(err.message));reader.readAsDataURL(file);};
$('removeImage').onclick=()=>feature('meta',{nodes:[S.selected],patch:{image:null}}).catch(e=>toast(e.message));
for(const button of document.querySelectorAll('#layouts button'))button.onclick=()=>feature('settings',{patch:{layout:button.dataset.value}}).then(fit).catch(e=>toast(e.message));
for(const [id,key,convert] of [['theme','theme',String],['lineType','lineType',String],['lineWidth','lineWidth',Number],['spacing','spacing',String],['background','background',String]])$(id).onchange=()=>feature('settings',{patch:{[key]:convert($(id).value)}}).catch(e=>toast(e.message));
$('resetBackground').onclick=()=>feature('settings',{patch:{background:null}}).catch(e=>toast(e.message));$('resetStyles').onclick=()=>{if(confirm('清除所有节点的自定义字体、形状和颜色？'))feature('settings',{patch:{},clearStyles:true}).catch(e=>toast(e.message));};

function flatBranch(id){const branch={roots:[id],nodes:{}},stack=[id];while(stack.length){const ident=stack.pop(),n=S.doc.nodes[ident];if(!n)continue;branch.nodes[ident]={title:n.title,notes:n.notes,color:n.color,style:n.style,meta:n.meta,children:[...n.children]};for(let i=n.children.length-1;i>=0;i--)stack.push(n.children[i]);}return branch;}
function copyBranch(){if(!current())return;S.clipboard=flatBranch(S.selected);navigator.clipboard?.writeText(JSON.stringify({mindcollab:true,branch:S.clipboard})).catch(()=>{});toast('已复制当前分支。',1500);}
async function pasteBranch(){let payload=S.clipboard?{branch:S.clipboard}:null;try{const value=JSON.parse(await navigator.clipboard.readText());if(value?.mindcollab&&value.branch?.nodes)payload={branch:value.branch};else if(value?.mindcollab&&Array.isArray(value.trees))payload={trees:value.trees};}catch{}if(!payload)return toast('剪贴板中没有可粘贴的导图分支。');feature('paste',{parent:S.selected,...payload}).catch(e=>toast(e.message));}
$('addParent').onclick=()=>feature('add_parent',{node:S.selected}).catch(e=>toast(e.message));
function editRelationship(item){const box=document.createElement('div');box.className='form-stack';const input=document.createElement('input');input.value=item.title||'';input.maxLength=120;input.placeholder='输入关系说明（最多 120 字）';const save=document.createElement('button');save.className='primary';save.textContent='保存关系说明';save.onclick=()=>feature('relationship',{update:item.id,title:input.value}).then(()=>{$('modal').close();toast('关系说明已保存并同步。',1800);}).catch(e=>toast(e.message));box.append(input,save);modal('编辑关系说明',box);setTimeout(()=>{input.focus();input.select();},20);}
function relationshipManager(){const box=document.createElement('div');box.className='form-stack';const selectedPair=[...S.selection].filter(id=>S.doc.nodes[id]);const title=document.createElement('p');title.textContent=selectedPair.length===2?'已选择两个主题，可直接添加它们之间的关系。':`从「${current().title}」添加关系，或删除与它关联的关系线。`;box.append(title);const related=(S.doc.relationships||[]).filter(item=>item.from===S.selected||item.to===S.selected);const relatedIds=new Set(related.map(item=>item.from===S.selected?item.to:item.from));if(related.length){const list=document.createElement('div');list.className='decoration-list';for(const item of related){const row=document.createElement('div'),label=document.createElement('span'),edit=document.createElement('button'),remove=document.createElement('button');label.textContent=`${S.doc.nodes[item.from]?.title||'?'} → ${S.doc.nodes[item.to]?.title||'?'}${item.title?`：${item.title}`:''}`;edit.textContent='编辑';edit.onclick=()=>editRelationship(item);remove.textContent='删除';remove.className='danger';remove.onclick=()=>feature('relationship',{delete:item.id}).then(relationshipManager).catch(e=>toast(e.message));row.append(label,edit,remove);list.append(row);}box.append(list);}const input=document.createElement('input');input.maxLength=120;input.placeholder='关系说明（可选）';const add=document.createElement('button');add.className='primary';add.textContent=selectedPair.length===2?'添加所选主题的关系线':'添加关系线';if(selectedPair.length===2){const [from,to]=selectedPair;const exists=(S.doc.relationships||[]).some(item=>new Set([item.from,item.to]).size===2&&new Set([item.from,item.to]).has(from)&&new Set([item.from,item.to]).has(to));add.disabled=exists;add.title=exists?'这两个主题之间已经存在关系线。':'';add.onclick=()=>feature('relationship',{item:{from,to,title:input.value.trim()}}).then(()=>{$('modal').close();toast('关系线已添加并同步。',1800);}).catch(e=>toast(e.message));box.append(input,add);modal('关系管理',box);return;}const select=document.createElement('select');for(const n of Object.values(S.doc.nodes).filter(n=>n.id!==S.selected)){const option=document.createElement('option');option.value=n.id;option.textContent=relatedIds.has(n.id)?`${n.title}（已有关系）`:n.title;option.disabled=relatedIds.has(n.id);select.append(option);}add.disabled=select.options.length===0||Array.from(select.options).every(option=>option.disabled);add.onclick=()=>feature('relationship',{item:{from:S.selected,to:select.value.trim(),title:input.value.trim()}}).then(relationshipManager).catch(e=>toast(e.message));box.append(select,input,add);modal('关系管理',box);}
$('relationship').onclick=relationshipManager;
function showSummaryDialog({item=null,topics=[]}={}){const creating=!item,box=document.createElement('div');box.className='form-stack';if(creating&&topics.length>1){const hint=document.createElement('p');hint.textContent=`将为所选 ${topics.length} 个主题添加共同概要。`;box.append(hint);}const input=document.createElement('input');input.value=item?.title||'';input.maxLength=120;input.placeholder='输入概要文字（最多 120 字）';const save=document.createElement('button');save.className='primary';save.textContent='保存概要';save.onclick=()=>{const title=input.value.trim(),op=creating?{item:{kind:'summary',topics,title}}:{update:item.id,title};feature('annotation',op).then(()=>{$('modal').close();toast(creating?'概要已添加并同步。':'概要已保存并同步。',1800);}).catch(e=>toast(e.message));};box.append(input,save);modal(creating?'添加概要':'编辑概要',box);setTimeout(()=>{input.focus();input.select();},20);}
function toggleAnnotation(kind){const topics=topicsFor().filter(id=>S.doc?.nodes[id]);if(!topics.length)return;const existing=selectedAnnotation(kind);if(existing){feature('annotation',{delete:existing.id}).then(()=>toast(kind==='boundary'?'边界已取消。':'概要已取消。',1800)).catch(e=>toast(e.message));return;}if(kind==='summary'){showSummaryDialog({topics});return;}feature('annotation',{item:{kind,topics,title:''}}).catch(e=>toast(e.message));}
$('boundary').onclick=()=>toggleAnnotation('boundary');
$('summary').onclick=()=>toggleAnnotation('summary');
function showSearch(){const box=document.createElement('div');box.className='search-box';const input=document.createElement('input');input.placeholder='搜索主题、备注或标签';const results=document.createElement('div');results.className='search-results';const run=()=>{const q=input.value.trim().toLowerCase();results.replaceChildren();if(!q)return;for(const n of Object.values(S.doc.nodes).filter(n=>[n.title,n.notes,...(n.meta?.labels||[])].join(' ').toLowerCase().includes(q)).slice(0,80)){const b=document.createElement('button');b.innerHTML=`<strong></strong><small></small>`;b.querySelector('strong').textContent=n.title;b.querySelector('small').textContent=(n.notes||n.meta?.labels?.join(' · ')||'主题').slice(0,80);b.onclick=()=>{$('modal').close();S.collapsed.clear();select(n.id);render();centerNode(n.id);};results.append(b);}};input.oninput=run;box.append(input,results);modal('搜索导图',box);setTimeout(()=>input.focus(),20);}
function showOutline(){const box=document.createElement('div'),fragment=document.createDocumentFragment(),stack=[[viewRoot(),0]];box.className='outline-list';while(stack.length){const[id,depth]=stack.pop(),n=S.doc.nodes[id],b=document.createElement('button');b.style.paddingLeft=`${12+depth*18}px`;b.textContent=n.title;b.onclick=()=>{$('modal').close();for(const parent of ancestorIds(S.doc.nodes,id))S.collapsed.delete(parent);select(id);render();centerNode(id);};fragment.append(b);for(let i=n.children.length-1;i>=0;i--)stack.push([n.children[i],depth+1]);}box.append(fragment);modal('大纲',box);}
