function manageDecorations(){const box=document.createElement('div');box.className='decoration-list';const entries=[...(S.doc.relationships||[]).map(item=>({type:'relationship',item,label:`关系：${S.doc.nodes[item.from]?.title||'?'} → ${S.doc.nodes[item.to]?.title||'?'}`})),...(S.doc.annotations||[]).map(item=>({type:'annotation',item,label:`${item.kind==='boundary'?'边界':'概要'}：${item.title||item.topics.map(id=>S.doc.nodes[id]?.title).filter(Boolean).join('、')}`}))];if(!entries.length){const p=document.createElement('p');p.textContent='当前没有关系线、边界或概要。';box.append(p);}for(const entry of entries){const row=document.createElement('div'),span=document.createElement('span'),actions=document.createElement('div');span.textContent=entry.label;if(entry.type==='relationship'){const edit=document.createElement('button');edit.textContent='编辑';edit.onclick=()=>editRelationship(entry.item);actions.append(edit);}if(entry.type==='annotation'&&entry.item.kind==='summary'){const edit=document.createElement('button');edit.textContent='编辑';edit.onclick=()=>editSummary(entry.item);actions.append(edit);}const remove=document.createElement('button');remove.textContent='删除';remove.className='danger';remove.onclick=()=>feature(entry.type,{delete:entry.item.id}).then(manageDecorations).catch(e=>toast(e.message));actions.append(remove);row.append(span,actions);box.append(row);}modal('管理关系与标注',box);}
function centerNode(id){const p=S.positions.get(id),rect=$('canvas').getBoundingClientRect();if(!p)return;S.transform.x=rect.width/2-p.x*S.transform.k;S.transform.y=rect.height/2-p.y*S.transform.k;applyTransform();}
