$('moreTools').onclick=()=>{const box=document.createElement('div');box.className='command-grid';for(const [label,fn,keep] of [['复制分支',copyBranch],['粘贴为子主题',pasteBranch],['展开全部',()=>{S.collapsed.clear();render();fit();}],['折叠当前分支',()=>$('collapse').click()],['管理关系与标注',manageDecorations,true]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(!keep)$('modal').close();fn();};box.append(b);}modal('更多操作',box);};
for(const id of ['nodeTitle','nodeNotes'])$(id).addEventListener('input',()=>{if(!S.draft)return;S.draft.title=$('nodeTitle').value;S.draft.notes=$('nodeNotes').value;S.draft.dirty=true;preserveDraft();updateInspector();});
function select(id,focus=false,additive=false){if(!S.doc?.nodes[id])return;if(S.focusRoot&&!S.focusMembers?.has(id)){leaveFocus(true,false);render();}if(S.inline&&S.inline.node!==id)finishInline(true);preserveDraft();if(additive){if(S.selection.has(id)){S.selection.delete(id);if(S.selected===id)S.selected=[...S.selection].at(-1)||null;}else{S.selection.add(id);S.selected=id;}if(!S.selected){highlightLineage();updateDisabled();presence();return;}}else{S.selection=new Set([id]);S.selected=id;}loadInspector();highlightLineage();presence();updateAnnotationActions();if(focus)startInline(id);}
function positionInline(){if(!S.inline)return;const p=S.positions.get(S.inline.node);if(!p)return;const t=S.transform,el=$('inlineEditor'),w=Math.max(30,p.w*t.k),h=Math.max(24,p.h*t.k),fontSize=Math.max(7,Math.min(26,(S.doc.nodes[S.inline.node].style?.fontSize||14)*t.k));el.style.left=`${p.x*t.k+t.x-w/2}px`;el.style.top=`${p.y*t.k+t.y-h/2}px`;el.style.width=`${w}px`;el.style.height=`${h}px`;el.style.fontSize=`${fontSize}px`;el.style.lineHeight='1.2';el.style.padding=`${Math.max(1,5*t.k)}px ${Math.max(2,8*t.k)}px`;el.style.borderRadius=`${Math.max(2,7*t.k)}px`;}
function startInline(id){if(!online()||!S.doc?.nodes[id])return;if(S.inline?.node===id)return;if(S.inline)finishInline(true);const n=S.doc.nodes[id];S.inline={node:id,expected:n.rev.title,original:n.title};const el=$('inlineEditor');el.value=S.draft?.node===id&&S.draft.dirty?S.draft.title:n.title;el.hidden=false;positionInline();el.focus();el.select();}
async function finishInline(save){const state=S.inline;if(!state)return;const value=$('inlineEditor').value.trim();S.inline=null;$('inlineEditor').hidden=true;if(save&&value&&value!==state.original){try{await operation({kind:'edit',node:state.node,field:'title',value,expected:state.expected});const latest=S.doc.nodes[state.node];if(S.draft?.node===state.node&&latest){S.draft.title=latest.title;S.draft.base.title=latest.rev.title;S.draft.dirty=S.draft.notes!==latest.notes;if(S.draft.dirty)preserveDraft();else{localStorage.removeItem(draftKey(S.doc.id,state.node));loadInspector();}}}catch(e){if(S.doc.nodes[state.node]){select(state.node);S.draft.title=value;S.draft.dirty=true;preserveDraft();loadInspector();}toast(e.message);}}$('canvas').focus({preventScroll:true});}
$('inlineEditor').onblur=()=>{if(S.inline)finishInline(true);};
$('inlineEditor').onkeydown=async e=>{e.stopPropagation();if(e.isComposing)return;const ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(ctrl&&key==='s'){e.preventDefault();await finishInline(true);}else if(ctrl&&(key==='z'||key==='y')&&$('inlineEditor').value===S.inline?.original){e.preventDefault();await finishInline(false);undoRedo(key==='y'||e.shiftKey);}else if(e.key==='Escape'){e.preventDefault();finishInline(false);}else if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();await finishInline(true);}else if(e.key==='Tab'){e.preventDefault();await finishInline(true);$('addChild').click();}};
function presence(){if(online())S.socket.send(JSON.stringify({type:'presence',selected:S.selected}));}
function operation(op,track=true){if(!online())return Promise.reject(Error('连接已断开，请等待重连后再操作。'));const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);const request=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join(''),selected=S.selected;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{S.pending.delete(request);updateDisabled();reject(Error('未收到保存确认，请等待重连并核对最新状态。'));},30000);S.pending.set(request,{resolve:result=>{if(track&&result.undo_token){S.undo.push({token:result.undo_token,selected});if(S.undo.length>100)S.undo.shift();S.redo=[];}updateDisabled();resolve(result);},reject,timer});updateDisabled();$('saveStatus').textContent='正在保存…';S.socket.send(JSON.stringify({type:'operation',request,op}));});}
async function undoRedo(redo=false){if(S.undoBusy||S.pending.size)return;if(S.inline)await finishInline(true);const from=redo?S.redo:S.undo,to=redo?S.undo:S.redo;if(!from.length)return;S.undoBusy=true;updateDisabled();const entry=from.at(-1),selected=S.selected;try{const result=await operation({kind:'undo',token:entry.token,selected:entry.selected},false);from.pop();to.push({token:result.undo_token,selected});toast(redo?'已重做':'已撤销',1500);}catch(e){toast(e.message,8000);}finally{S.undoBusy=false;updateDisabled();}}
$('undo').onclick=()=>undoRedo();$('redo').onclick=()=>undoRedo(true);
function perform(op){operation(op).catch(e=>toast(e.message));}
$('saveNode').onclick=async()=>{const draft=S.draft,n=current();if(!draft||!n||draft.busy)return;if(!draft.title.trim())return toast('主题文字不能为空。');
 if((draft.base.title!==n.rev.title||draft.base.notes!==n.rev.notes)&&!confirm('同事已修改这个节点。是否用你的草稿提交？取消可继续保留草稿。'))return;
 draft.busy=true;updateDisabled();try{for(const field of ['title','notes']){const latest=S.doc.nodes[draft.node];if(latest[field]!==draft[field])await operation({kind:'edit',node:draft.node,field,value:draft[field],expected:latest.rev[field]});}
 localStorage.removeItem(draftKey(S.doc.id,draft.node));draft.dirty=false;if(S.selected===draft.node)loadInspector();toast('已保存并同步。',1800);
 }catch(e){toast(e.message);preserveDraft();}finally{draft.busy=false;updateDisabled();}};

const deletingDocuments=new Set();
async function deleteDocument(id){if(deletingDocuments.has(id))return;deletingDocuments.add(id);try{const doc=await api(`/api/documents/${id}`),title=doc.nodes[doc.root].title;if(!confirm(`将整张导图「${title}」（${Object.keys(doc.nodes).length} 个节点）移入回收站？\n导图、历史版本和撤销记录会保留 30 天，期间可以恢复；超过 30 天后自动永久删除。正在查看它的协作者会退出该导图。\n原始 XMind 文件不会被删除。`))return;await api(`/api/documents/${id}?expected_version=${doc.version}`,{method:'DELETE'});await documentDeleted(id);toast('导图已移入回收站，可在回收站中恢复。',6000);}catch(e){toast(e.message);refreshDocuments().catch(()=>{});}finally{deletingDocuments.delete(id);}}
function clearDocument(){++S.generation;if(S.socket){S.socket.onclose=null;S.socket.onmessage=null;S.socket.close();S.socket=null;}preserveDraft();S.inline=null;$('inlineEditor').hidden=true;for(const p of S.pending.values()){clearTimeout(p.timer);p.reject(Error('导图已被删除，操作无法继续。'));}S.pending.clear();resetFocusView();S.doc=null;S.selected=null;S.selection.clear();S.draft=null;S.undo=[];S.redo=[];S.users=[];S.collapsed.clear();S.positions.clear();for(const id of ['annotations','edges','relations','nodes','relationLabels'])$(id).replaceChildren();drawPresence();$('nodeTitle').value='';$('nodeNotes').value='';document.querySelector('.inspector').inert=true;setStatus(false);$('connection').textContent='未打开导图';$('saveStatus').textContent='请选择或新建导图';$('docTitle').textContent='未打开导图';$('nodeStats').textContent='—';$('history').disabled=true;$('export').disabled=true;$('contextMenu').hidden=true;$('empty').hidden=false;if($('modal').open)$('modal').close();history.replaceState(null,'',location.pathname);}
async function documentDeleted(id){if(S.doc?.id===id){clearDocument();toast('当前导图已移入回收站，可在回收站中恢复。',6000);}await refreshDocuments();}
function trashDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'未知时间':date.toLocaleString();}
function trashRemaining(value){const expires=new Date(new Date(value).getTime()+30*86400000),days=Math.max(0,Math.ceil((expires-Date.now())/86400000));return days?`还可恢复 ${days} 天 · ${expires.toLocaleDateString()} 后自动删除`:'即将自动删除';}
async function openTrash(){try{const items=await api('/api/trash'),box=document.createElement('div');const intro=document.createElement('p');intro.className='trash-intro';intro.textContent='移入回收站的导图会保留 30 天。到期后系统会在启动或打开回收站时自动永久清理。';box.append(intro);if(!items.length){const empty=document.createElement('div');empty.className='trash-empty';empty.textContent='回收站是空的';box.append(empty);}else{const list=document.createElement('div');list.className='trash-list';for(const item of items){const row=document.createElement('div');row.className='trash-row';const info=document.createElement('div');info.className='trash-info';const title=document.createElement('strong');title.className='trash-title';title.textContent=item.title;const meta=document.createElement('small');meta.className='trash-meta';meta.textContent=`删除于 ${trashDate(item.deleted_at)} · ${trashRemaining(item.deleted_at)}`;info.append(title,meta);const actions=document.createElement('div');actions.className='trash-actions';const restore=document.createElement('button');restore.textContent='恢复';const purge=document.createElement('button');purge.textContent='彻底删除';purge.className='danger';restore.onclick=async()=>{restore.disabled=true;purge.disabled=true;try{await api(`/api/trash/${item.id}/restore`,{method:'POST'});toast(`已恢复「${item.title}」。`,2200);$('modal').close();await refreshDocuments();}catch(e){toast(e.message);restore.disabled=false;purge.disabled=false;}};purge.onclick=async()=>{if(!confirm(`彻底删除「${item.title}」？\n\n此操作会永久删除导图、历史版本和撤销记录，无法恢复。`))return;restore.disabled=true;purge.disabled=true;try{await api(`/api/trash/${item.id}`,{method:'DELETE'});toast(`已彻底删除「${item.title}」。`,2200);await openTrash();await refreshDocuments();}catch(e){toast(e.message);restore.disabled=false;purge.disabled=false;}};actions.append(restore,purge);row.append(info,actions);list.append(row);}box.append(list);}modal('回收站',box);}catch(e){toast(e.message);}}
async function renameDocument(){if(!S.doc||!online())return;const oldTitle=S.doc.nodes[S.doc.root].title,value=prompt('请输入新的导图名称：',oldTitle);if(value===null)return;const title=value.trim();if(!title)return toast('导图名称不能为空。');if(title.length>200)return toast('导图名称不能超过 200 个字符。');try{await operation({kind:'rename',value,expected_version:S.doc.version});toast('导图名称已更新并同步。',1800);}catch(e){toast(e.message);}}
async function refreshDocuments(){const docs=await api('/api/documents');$('documents').replaceChildren();$('docCount').textContent=docs.length;for(const d of docs){const row=document.createElement('div');row.className='doc-item'+(d.id===S.doc?.id?' active':'');row.dataset.document=d.id;const b=document.createElement('button');b.className='doc-open';const label=d.sheet_title&&d.sheet_title!==d.title?`${d.sheet_title} · ${d.title}`:d.title;b.title=label;const icon=document.createElement('i');icon.dataset.lucide='file-text';icon.className='doc-icon';const span=document.createElement('span');span.className='doc-text';span.textContent=label;b.append(icon,span);b.onclick=()=>openDocument(d.id);const remove=document.createElement('button');remove.className='doc-delete';remove.title=`移入回收站：${d.title}`;remove.setAttribute('aria-label',remove.title);const trash=document.createElement('i');trash.dataset.lucide='trash-2';remove.append(trash);remove.onclick=()=>deleteDocument(d.id);row.append(b,remove);$('documents').append(row);}iconize();return docs;}
async function openDocument(id){if(S.inline)await finishInline(true);preserveDraft();rememberView();resetFocusView();S.undo=[];S.redo=[];const generation=++S.generation;if(S.socket){S.socket.onclose=null;S.socket.close();}for(const p of S.pending.values()){clearTimeout(p.timer);p.reject(Error('已切换文档；请核对原文档的保存状态。'));}S.pending.clear();S.collapsed.clear();S.selection.clear();S.draft=null;setStatus(false);try{const doc=await api(`/api/documents/${id}`);if(generation!==S.generation)return;S.doc=doc;S.selected=doc.root;S.selection=new Set([doc.root]);applyCanvasBackground();history.replaceState(null,'',`?doc=${id}`);$('docTitle').textContent=doc.nodes[doc.root].title;$('empty').hidden=true;document.querySelector('.inspector').inert=false;$('history').disabled=false;$('export').disabled=false;loadInspector();const restored=restoreView(id);render();if(!restored)fit();refreshDocuments();connect(id,generation);}catch(e){if(generation!==S.generation)return;clearDocument();toast(e.message);}}
