window.addEventListener('pointermove',e=>{if(!drag)return;if(drag.type==='pan'){S.transform.x=drag.tx+e.clientX-drag.x;S.transform.y=drag.ty+e.clientY-drag.y;applyTransform();return;}if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<7&&!drag.moved)return;drag.moved=true;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]');document.querySelectorAll('.drop').forEach(el=>el.classList.remove('drop'));drag.target=target?.dataset.node;if(drag.target!==drag.id)target?.classList.add('drop');});
window.addEventListener('pointerup',()=>{if(!drag)return;const d=drag;drag=null;$('canvas').style.cursor='';document.querySelectorAll('.drop').forEach(el=>el.classList.remove('drop'));if(d.type==='node'&&d.moved&&d.target&&d.target!==d.id&&d.id!==S.doc.root)perform({kind:'move',node:d.id,parent:d.target,expected_version:S.doc.version});});
let canvasSize=null;
new ResizeObserver(()=>{const {width,height}=$('canvas').getBoundingClientRect();if(S.doc&&canvasSize){S.transform.x+=(width-canvasSize.width)/2;S.transform.y+=(height-canvasSize.height)/2;applyTransform();}canvasSize={width,height};}).observe($('canvas'));

function revealNode(id){const p=S.positions.get(id);if(!p)return;const {width,height}=$('canvas').getBoundingClientRect(),t=S.transform,halfWidth=Math.max(150,p.w*t.k)/2,halfHeight=Math.max(48,p.h*t.k)/2;
 const shift=(center,half,size)=>{const margin=24;if(half*2+margin*2>size)return size/2-center;if(center-half<margin)return margin-(center-half);if(center+half>size-margin)return size-margin-(center+half);return 0;};
 t.x+=shift(p.x*t.k+t.x,halfWidth,width);t.y+=shift(p.y*t.k+t.y,halfHeight,height);applyTransform();}

$('addChild').onclick=async()=>{const n=current();if(!n)return;S.collapsed.delete(n.id);try{const result=await operation({kind:'add',parent:n.id});select(result.selected);revealNode(result.selected);startInline(result.selected);}catch(e){toast(e.message);}};
$('addSibling').onclick=async()=>{const n=current();if(!n?.parent)return;try{const result=await operation({kind:'add',parent:n.parent,after:n.id});select(result.selected);revealNode(result.selected);startInline(result.selected);}catch(e){toast(e.message);}};
$('deleteNode').onclick=()=>{const n=current();if(!n||n.id===S.doc.root||!online())return;if(!S.deleteConfirmed){if(!confirm(`删除「${n.title}」及其 ${countBranch(n.id)-1} 个子节点？历史中会保留此前版本。\n确认后，本页面后续删除不再提示；刷新或重新打开页面后恢复提示。误删可按 Ctrl+Z 撤销。`))return;S.deleteConfirmed=true;}perform({kind:'delete',node:n.id,expected_version:S.doc.version});};
$('collapse').onclick=()=>toggleCollapse(S.selected);
for(const[id,direction]of[['moveUp',-1],['moveDown',1]])$(id).onclick=()=>perform({kind:'reorder',node:S.selected,direction,expected_version:S.doc.version});
document.addEventListener('keydown',e=>{if(e.isComposing||$('identityGate').open)return;const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName),ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(ctrl&&key==='f'&&!editing){e.preventDefault();showSearch();return;}if($('modal').open)return;if(ctrl&&key==='s'){e.preventDefault();if(S.inline)finishInline(true);else if(S.draft?.dirty)$('saveNode').click();else toast('已提交的内容自动保存到本机数据库。',2200);return;}if(ctrl&&(key==='z'||key==='y')&&!editing){e.preventDefault();undoRedo(key==='y'||e.shiftKey);return;}if(ctrl&&key==='c'&&!editing){e.preventDefault();copyBranch();return;}if(ctrl&&key==='v'&&!editing){e.preventDefault();pasteBranch();return;}if(ctrl&&e.key==='Enter'){e.preventDefault();$('saveNode').click();return;}if(editing||!S.doc)return;if(e.key==='Tab'){e.preventDefault();$('addChild').click();}else if(e.key==='Enter'){e.preventDefault();$('addSibling').click();}else if(e.key==='Delete'){e.preventDefault();$('deleteNode').click();}else if(e.key==='F2'){e.preventDefault();select(S.selected,true);}});
window.addEventListener('beforeunload',e=>{if(S.draft?.dirty||S.pending.size){preserveDraft();e.preventDefault();e.returnValue='';}});
$('newDoc').onclick=async()=>{try{const d=await api('/api/documents',{method:'POST'});await openDocument(d.id);select(d.root,true);}catch(e){toast(e.message);}};
$('trash').onclick=()=>openTrash();$('renameDoc').onclick=()=>renameDocument();
function showImportResult(result){
 const documents=result.documents||[{id:result.document.id,title:result.document.nodes[result.document.root].title}],box=document.createElement('div');
 const intro=document.createElement('p');intro.textContent=documents.length>1?`已导入全部 ${documents.length} 个工作表，共 ${documents.reduce((sum,d)=>sum+(d.node_count||0),0)} 个节点。每个工作表独立保存，可在左侧“全部导图”切换编辑。`:'导入完成，内容已保存到本机数据库。';box.append(intro);
 const list=document.createElement('div');list.className='import-sheet-list';
 for(const [index,doc] of documents.entries()){const button=document.createElement('button');button.className='secondary wide';button.dataset.importedDocument=doc.id;button.textContent=`${index+1}. ${doc.sheet_title||doc.title}${doc.node_count===undefined?'':` · ${doc.node_count} 个节点`}`;button.onclick=async()=>{$('modal').close();await openDocument(doc.id);};list.append(button);}box.append(list);
 for(const warning of result.warnings||[]){const p=document.createElement('p');p.textContent=warning;box.append(p);}modal('导入完成',box);
}
$('importDoc').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>128*1024*1024){toast('文件不能超过 128 MB。');e.target.value='';return;}$('importDoc').disabled=true;try{const form=new FormData();form.append('file',file);const r=await api('/api/import',{method:'POST',body:form});await openDocument(r.document.id);showImportResult(r);}catch(err){toast(err.message,8000);}finally{e.target.value='';$('importDoc').disabled=false;}};
$('share').onclick=async()=>{const box=document.createElement('div'),p=document.createElement('p');p.textContent='在同一网络中，将链接发送给同事。其他人访问时，请把 127.0.0.1 或 localhost 替换为这台电脑的局域网 IP。此链接没有账号权限，获得链接的人可编辑。';const input=document.createElement('input');input.readOnly=true;input.value=location.href;const b=document.createElement('button');b.className='primary';b.textContent='复制链接';b.onclick=async()=>{try{await navigator.clipboard.writeText(input.value);toast('链接已复制。',1800);}catch{input.focus();input.select();toast('请按 Ctrl+C 复制选中的链接。');}};box.append(p,input,b);modal('邀请协作',box);};
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fileTitle(){return S.doc.nodes[S.doc.root].title.replace(/[\\/:*?"<>|]/g,'_').slice(0,60);}
function exportSvg(){const el=$('map').cloneNode(true),box=bounds(S.positions.values()),minX=box.minX-55,maxX=box.maxX+90,minY=box.minY-55,maxY=box.maxY+55;el.querySelector('#viewport').removeAttribute('transform');el.setAttribute('viewBox',`${minX} ${minY} ${maxX-minX} ${maxY-minY}`);el.setAttribute('width',maxX-minX);el.setAttribute('height',maxY-minY);el.setAttribute('xmlns','http://www.w3.org/2000/svg');el.querySelectorAll('text').forEach(t=>t.setAttribute('font-family','Microsoft YaHei, sans-serif'));el.querySelectorAll('[tabindex]').forEach(t=>t.removeAttribute('tabindex'));return {text:new XMLSerializer().serializeToString(el),width:maxX-minX,height:maxY-minY};}
async function exportPng(){const out=exportSvg(),img=new Image(),url=URL.createObjectURL(new Blob([out.text],{type:'image/svg+xml'}));img.onload=()=>{const scale=Math.min(3,Math.max(1,2400/out.width)),canvas=document.createElement('canvas');canvas.width=Math.ceil(out.width*scale);canvas.height=Math.ceil(out.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle=S.doc.background||themeDefaults[S.doc.theme||'original'].background;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.scale(scale,scale);ctx.drawImage(img,0,0);URL.revokeObjectURL(url);canvas.toBlob(blob=>download(fileTitle()+'.png',blob,'image/png'),'image/png');};img.onerror=()=>{URL.revokeObjectURL(url);toast('PNG 生成失败，请改用 SVG。');};img.src=url;}
$('export').onclick=()=>{if(!S.doc)return;const box=document.createElement('div');box.className='export-options';for(const[label,fn]of[
 ['XMind · 可在 XMind 中继续编辑',()=>location.href=`/api/documents/${S.doc.id}/export/xmind`],
 ['JSON · 可重新导入的完整备份',()=>download(fileTitle()+'.json',JSON.stringify(S.doc,null,2),'application/json')],
 ['Markdown · 节点层级与备注',()=>{const rows=[],stack=[[S.doc.root,0]];while(stack.length){const[id,depth]=stack.pop(),n=S.doc.nodes[id],indent='  '.repeat(depth);rows.push(`${indent}- ${n.title.replace(/\n/g,' ')}`);if(n.notes){const noteIndent=indent+'  ';rows.push(noteIndent+n.notes.replace(/\n/g,'\n'+noteIndent));}for(let i=n.children.length-1;i>=0;i--)stack.push([n.children[i],depth+1]);}download(fileTitle()+'.md',rows.join('\n')+'\n','text/markdown;charset=utf-8');}],
 ['PNG · 高清图片',exportPng],['SVG · 可缩放矢量图',()=>{const out=exportSvg();download(fileTitle()+'.svg',out.text,'image/svg+xml');}]
 ]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();$('modal').close();};box.append(b);}modal('导出思维导图',box);};
$('history').onclick=async()=>{if(!S.doc)return;const id=S.doc.id,box=document.createElement('div'),intro=document.createElement('p'),list=document.createElement('div'),pager=document.createElement('div');let before=null,loading=false;list.className='history-list';pager.className='history-pager';box.append(intro,list,pager);const load=async()=>{if(loading)return;loading=true;pager.replaceChildren();try{const raw=await api(`/api/documents/${id}/history${before===null?'':`?before=${encodeURIComponent(before)}`}`),legacy=Array.isArray(raw),page=legacy?{items:raw,total:raw.length,has_more:false}:raw;if(!page||!Array.isArray(page.items))throw Error('历史版本数据格式无效，请重启服务后重试。');intro.textContent=legacy?`当前服务返回 ${page.total} 个旧版历史版本。记录仍在；重启 GNN 服务后可启用 3,000 条记录和修改详情。`:`当前保留 ${Number.isFinite(page.total)?page.total:page.items.length} / 3,000 个历史版本。记录显示操作者与修改内容；打开副本不会影响当前协作者。`;for(const v of page.items){const row=document.createElement('div'),info=document.createElement('div'),head=document.createElement('div'),version=document.createElement('strong'),actor=document.createElement('span'),summary=document.createElement('p'),time=document.createElement('small'),b=document.createElement('button');row.className='history-row';info.className='history-info';head.className='history-head';version.textContent=`版本 ${v.version}`;actor.textContent=v.actor||'未知操作者';summary.className='history-summary';summary.textContent=v.summary||'未记录详细操作（旧版本）';time.textContent=new Date(v.created).toLocaleString();head.append(version,actor);info.append(head,summary,time);b.textContent='打开为副本';b.onclick=async()=>{b.disabled=true;try{const d=await api(`/api/documents/${id}/history/${v.version}/copy`,{method:'POST'});$('modal').close();openDocument(d.id);}catch(e){toast(e.message);b.disabled=false;}};row.append(info,b);list.append(row);}before=page.has_more&&page.items.length?page.items.at(-1).version:null;if(before!==null){const more=document.createElement('button');more.className='secondary wide';more.textContent='加载更早的 100 条记录';more.onclick=load;pager.append(more);}}catch(e){toast(e.message);}finally{loading=false;}};modal('历史版本',box);await load();};
$('help').onclick=()=>{const box=document.createElement('div'),grid=document.createElement('div');grid.className='help-grid';for(const[key,label]of[['Tab','添加子节点'],['Enter','添加同级节点'],['F2 / 双击','就地编辑节点'],['Ctrl + Z','撤销导图操作'],['Ctrl + Shift + Z','重做导图操作'],['Delete','删除分支'],['滚轮','上下移动画布'],['Ctrl + 滚轮','缩放画布'],['Ctrl + Enter','保存右侧详情']]){const k=document.createElement('kbd');k.textContent=key;const s=document.createElement('span');s.textContent=label;grid.append(k,s);}for(const text of ['拖动空白处平移，拖动节点到另一节点调整层级。已提交的修改自动写入本机 data/mindcollab.sqlite3；导入只创建协作副本，不会修改原 XMind。','XMind 导入会尽量保留可识别的颜色、字号、粗斜体、节点形状、背景色及左右布局；图片、附件、关系线、边界、公式和复杂主题效果不能完整还原。早期已导入的导图需要重新导入原文件，才能读取新支持的样式。','撤销记录只保留在当前浏览器会话中；若相关节点已被其他人继续修改，为避免覆盖协作内容，系统会拒绝撤销。可使用“历史”打开旧版本副本。']){const p=document.createElement('p');p.textContent=text;box.append(p);}box.prepend(grid);modal('使用帮助',box);};
async function init(){try{const docs=await refreshDocuments();const id=new URLSearchParams(location.search).get('doc')||docs[0]?.id;if(id)await openDocument(id);else clearDocument();}catch(e){toast('无法连接本地服务：'+e.message,10000);}}
function normalizeIdentity(value){return value.trim().replace(/\s+/g,' ');}
function identityProblem(value){const name=normalizeIdentity(value),letters=name.match(/\p{L}/gu)||[];if(name.length<2||name.length>24||letters.length<2||!/^[-\p{L} .·•'’‐]+$/u.test(name))return '请输入 2–24 个字的真实姓名，只能包含文字、空格、间隔点、连字符或撇号。';if(['访客','游客','匿名','guest','anonymous'].includes(name.toLowerCase()))return '不能使用“访客”或“匿名”，请输入你的真实姓名。';return '';}
$('identityGate').addEventListener('cancel',e=>e.preventDefault());
$('identityForm').onsubmit=e=>{e.preventDefault();const name=normalizeIdentity($('identityName').value),problem=identityProblem(name);$('identityError').textContent=problem;if(problem){$('identityName').focus();return;}S.name=name;$('userName').value=name;$('userName').readOnly=true;$('userName').title='刷新页面后可重新填写姓名';$('identityGate').close();document.body.classList.remove('identity-pending');init();};
$('identityGate').showModal();$('identityName').focus();
